-- Phase 2 (part 2f): Non-Duro-Last Pricing (8 screens) + reusable pricing_catalog table.
-- Idempotent. RLS: authenticated read, admin-only write.

create table if not exists public.pricing_catalog (
  id text primary key,
  branch text not null,
  category text not null,
  data jsonb not null default '{}'::jsonb,
  sort integer not null default 0
);
alter table public.pricing_catalog enable row level security;
revoke all on public.pricing_catalog from anon;
drop policy if exists pricing_catalog_read on public.pricing_catalog;
create policy pricing_catalog_read on public.pricing_catalog for select to authenticated using (true);
drop policy if exists pricing_catalog_write on public.pricing_catalog;
create policy pricing_catalog_write on public.pricing_catalog for all to authenticated using (public.is_admin()) with check (public.is_admin());
insert into public.pricing_catalog (id, branch, category, data, sort)
select * from (values
  ('non_dl:roof_edge_blocking','non_dl','Roof Edge Blocking','{"columns": ["Description", "Price", "LaborPerUnit", "Labor Rate"], "rows": [{"Description": "½\" Wood Blocking", "Price": 0.0, "LaborPerUnit": 0, "Labor Rate": 45.0}, {"Description": "¾\" Wood Blocking", "Price": 0.0, "LaborPerUnit": 0, "Labor Rate": 45.0}, {"Description": "5/4\" Wood Blocking", "Price": 0.0, "LaborPerUnit": 0, "Labor Rate": 45.0}, {"Description": "2\" Wood Blocking", "Price": 0.0, "LaborPerUnit": 0, "Labor Rate": 45.0}, {"Description": "2\" x 6\" x 12''", "Price": 8.99, "LaborPerUnit": 0.25, "Labor Rate": 45.0}, {"Description": "2\" x 6\" x 12'' Treated", "Price": 14.29, "LaborPerUnit": 0.25, "Labor Rate": 45.0}, {"Description": "2\" x 8\" x 12''", "Price": 19.78, "LaborPerUnit": 0.25, "Labor Rate": 45.0}, {"Description": "2\" x 8\" x 12'' Treated", "Price": 17.89, "LaborPerUnit": 0.25, "Labor Rate": 45.0}, {"Description": "2\" x 10\" x 12''", "Price": 18.12, "LaborPerUnit": 0.25, "Labor Rate": 45.0}, {"Description": "2\" x 10\" x 12'' Treated", "Price": 23.39, "LaborPerUnit": 0.25, "Labor Rate": 45.0}, {"Description": "2\" x 12\" x 12''", "Price": 17.95, "LaborPerUnit": 0.25, "Labor Rate": 45.0}, {"Description": "2\" x 12\" x 12'' Treated", "Price": 29.59, "LaborPerUnit": 0.25, "Labor Rate": 45.0}, {"Description": "1\" x 4\" x 12''", "Price": 13.97, "LaborPerUnit": 0.25, "Labor Rate": 45.0}, {"Description": "1\" x 6\" x 12''", "Price": 11.18, "LaborPerUnit": 0.25, "Labor Rate": 45.0}, {"Description": "1\" x 8\" x 12''", "Price": 13.28, "LaborPerUnit": 0.25, "Labor Rate": 45.0}, {"Description": "1\" x 10\" x 12''", "Price": 18.72, "LaborPerUnit": 0.25, "Labor Rate": 45.0}, {"Description": "1\" x 12\" x 12''", "Price": 18.71, "LaborPerUnit": 0.25, "Labor Rate": 45.0}, {"Description": "5/4 \" x 12''", "Price": 15.08, "LaborPerUnit": 0.25, "Labor Rate": 45.0}, {"Description": "2\" x 4\" x 12''", "Price": 6.48, "LaborPerUnit": 0.25, "Labor Rate": 45.0}, {"Description": "2\" x 4\" x 12'' Treated", "Price": 10.38, "LaborPerUnit": 0.25, "Labor Rate": 45.0}], "help": "Wood blocking can be selected on the Roof Sections screen. If wood blocking is needed at the perimeter of the roof area at the roof level it will be priced out based on the lineal foot pricing you provide for this list of potential wood blocking options. The program uses a combination of blocking to make up the thickness of underlayment selected. You will have to manually add wood blocking and labor for any get quote or flute filler areas where wood blocking might be required. Provide alternate labor rates if required.", "extras": {}}'::jsonb,0),
